	WHERE m.project_id = 2828
	ORDER BY m.id, mi.source_file
	limit 426
),
final as (
	select * from cte1 
	union
	select * from cte2
	union
	select * from cte3
),
dos_dx as (
	select 
		f.*,
		dx.source_id,
		dos.nppes_provider_id ,
		hdp.npi ,
		hdp.first_name ,
		hdp.last_name ,
		dos.dos_from,
		dos.dos_to,
		dx.diagnosis_code,
		dx.vendor_status ,
		dx.vendor_comment ,
		dx.page,
		dx.page_to ,
		pos.code as "pos" 
	from final f
	join healthcare_data_chart hdc on hdc.id = f.chart_id
	join healthcare_data_chart_review_dos dos on dos.chart_id = f.chart_id 
	join healthcare_data_chart_review_dx dx on dx.chart_review_dos_id = dos.id
	left join nppes_provider_lookup  hdp on hdp.id = dos.nppes_provider_id 
	left join common_place_of_service pos on pos.id = dos.pos_id
	where (dx.source_type = 'claims' or dx.source_type = 'Claims')
),--select * from dos_dx;
claims as(
	select distinct
	 source_id as claimno
	,"InputMemberID" as memberid
	,"MemberLastName" as memberlastname
	,"MemberFirstName" as memberfirstname
	,"MemberGender" as gender
	,to_char("MemberDOB"::date, 'MM/DD/YYYY') as dateofbirth
	,replace("MemberMetalLevel", '.pdf', '') as membermetallevel --pdf file Name only not extension
	,npi as rendering_providerid --provider npi
	,last_name as rendering_providerlastname
	,(case when first_name = '' then last_name else first_name end) as rendering_providerfirstname
	,to_char(dos_from::date, 'MM/DD/YYYY') as servicestartdate
	,to_char(dos_to::date, 'MM/DD/YYYY') as servicethrudate
	--changed on 01-30-2026 after introduction of CPT code ingestion
	--,replace(c."ICD_CODE", '.', '') as diag_code -- NOT REQUIRED
	,diagnosis_code as code -- must load claims with no Dot
	,'ICD' as codetype -- must load claims with no Dot
	,page as page_no
	,vendor_status as vendor_status
	,vendor_comment as vendor_comment --mandetory field
	,"pos" as pos
	,'' as note_type
	,page_to as page_to
	--select distinct "ECLAT_Chart_ID"
	from dos_dx 
)
select * from claims;


------ charts mapping

with cte1 as (
	select
	    m.first_name                                          AS "MemberFirstName",
	    m.last_name                                           AS "MemberLastName",
	    m.gender                                              AS "MemberGender",
	    mi.source_file                                        AS "MemberMetalLevel",
	    m.member_id                                           AS "InputMemberID",
	    TO_CHAR(m.dob, 'MM/DD/YYYY')                          AS "MemberDOB",
	    CASE WHEN m.custom_1 = 'Yes' THEN '1' ELSE '0' END    AS "MemberESRD",
	    mi.chart_id 
	FROM healthcare_data_member m
	JOIN healthcare_data_member_info mi
	      ON mi.str_member_id = m.member_id
