pages as (
	select 
		hdc.pdf_page_count,
		hdc.id,
		CASE -- replace with actual project s3 path
        WHEN cf.file = '' THEN 's3://epp-prod-file-bucket/processed/1-Humana/2630-Confidence_Score_2020/Chart/charts_20260312/A021-000048_2026012611.none' --static value
        ELSE 's3://epp-prod-data-bucket/media/private/' || cf.file 
    END as file_source
	from healthcare_data_chart hdc
	join healthcare_data_chartfile cf on cf.chart_id = hdc.id
	where project_id = 2828
	and hdc.pdf_page_count <=30
), 
page_list as (
    select array_agg(file_source) as files
    from pages
)
select 
	str_member_id,
	files[1 + floor(random() * array_length(files, 1))::int] as file_source,
--	(select file_source from pages order by random() limit 1 ) as file_source,
	'Chart/Caresource/charts_20261001/' || filename as file_dest
from source 
cross join page_list;